import { useState } from "react";

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <span>{count}</span>
      <button type="button" onClick={() => setCount((c) => c + 1)}>
        Increment
      </button>
    </div>
  );
}

import { useEffect, useState } from "react";

export default function FetchUsers() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    fetch("https://jsonplaceholder.typicode.com/users", { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(setUsers)
      .catch((err) => {
        if (err.name !== "AbortError") setError(err);
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });

    return () => controller.abort();
  }, []);

  if (loading) return <p>Loading…</p>;
  if (error) return <p>Error: {error.message}</p>;

  return (
    <ul>
      {users.map((user) => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}

import { useMemo, useState } from "react";

const COLUMNS = ["name", "price", "qty"];

export default function FilterTable({ rows = [] }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState({ key: null, dir: 1 });

  const visible = useMemo(() => {
    const q = query.toLowerCase();
    const filtered = rows.filter((row) => row.name.toLowerCase().includes(q));
    if (!sort.key) return filtered;
    return filtered.toSorted((a, b) => {
      const x = a[sort.key];
      const y = b[sort.key];
      const cmp = typeof x === "string" ? x.localeCompare(y) : x - y;
      return cmp * sort.dir;
    });
  }, [rows, query, sort]);

  const total = visible.reduce((sum, row) => sum + row.price * row.qty, 0);

  function toggleSort(key) {
    setSort((prev) => (prev.key === key ? { key, dir: -prev.dir } : { key, dir: 1 }));
  }

  return (
    <div>
      <input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search" />
      <table>
        <thead>
          <tr>
            {COLUMNS.map((col) => (
              <th key={col} onClick={() => toggleSort(col)}>
                {col}
                {sort.key === col && (sort.dir === 1 ? " ▲" : " ▼")}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {visible.map((row, i) => (
            <tr key={`${row.name}-${i}`}>
              <td>{row.name}</td>
              <td>{row.price}</td>
              <td>{row.qty}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={2}>Total</td>
            <td>{total}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

export default function Hello({ name }) {
  return <p>Hello, {name}!</p>;
}

import { useCallback, useEffect, useState } from "react";

export default function KvBrowser({ baseUrl }) {
  const [keys, setKeys] = useState([]);
  const [selected, setSelected] = useState(null);
  const [value, setValue] = useState("");
  const [form, setForm] = useState({ key: "", value: "" });
  const [error, setError] = useState(null);

  const request = useCallback(
    async (path, options) => {
      const res = await fetch(`${baseUrl}/kv${path}`, options);
      if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
      return res;
    },
    [baseUrl]
  );

  const loadKeys = useCallback(async () => {
    try {
      const res = await request("");
      setKeys(await res.json());
    } catch (err) {
      setError(err.message);
    }
  }, [request]);

  useEffect(() => {
    loadKeys();
  }, [loadKeys]);

  async function showValue(key) {
    setError(null);
    try {
      const res = await request(`/${encodeURIComponent(key)}`);
      setSelected(key);
      setValue(await res.text());
    } catch (err) {
      setError(err.message);
    }
  }

  async function handleSubmit(event) {
    event.preventDefault();
    if (!form.key) return;
    setError(null);
    try {
      await request(`/${encodeURIComponent(form.key)}`, { method: "PUT", body: form.value });
      if (selected === form.key) setValue(form.value);
      setForm({ key: "", value: "" });
    } catch (err) {
      setError(err.message);
    }
    await loadKeys();
  }

  async function remove(key) {
    setError(null);
    try {
      await request(`/${encodeURIComponent(key)}`, { method: "DELETE" });
      if (selected === key) {
        setSelected(null);
        setValue("");
      }
    } catch (err) {
      setError(err.message);
    }
    await loadKeys();
  }

  return (
    <div>
      {error && <p role="alert">Error: {error}</p>}
      <form onSubmit={handleSubmit}>
        <input
          placeholder="Key"
          value={form.key}
          onChange={(e) => setForm((f) => ({ ...f, key: e.target.value }))}
        />
        <input
          placeholder="Value"
          value={form.value}
          onChange={(e) => setForm((f) => ({ ...f, value: e.target.value }))}
        />
        <button type="submit">Save</button>
      </form>
      <ul>
        {keys.map((key) => (
          <li key={key}>
            <button type="button" onClick={() => showValue(key)}>
              {key}
            </button>
            <button type="button" onClick={() => remove(key)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
      {selected !== null && (
        <div>
          <h3>{selected}</h3>
          <pre>{value}</pre>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";

export default function Todo() {
  const [text, setText] = useState("");
  const [items, setItems] = useState([]);

  function handleSubmit(event) {
    event.preventDefault();
    const value = text.trim();
    if (!value) return;
    setItems((prev) => [...prev, { id: crypto.randomUUID(), text: value }]);
    setText("");
  }

  function remove(id) {
    setItems((prev) => prev.filter((item) => item.id !== id));
  }

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={text} onChange={(e) => setText(e.target.value)} />
        <button type="submit">Add</button>
      </form>
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            {item.text}
            <button type="button" onClick={() => remove(item.id)}>
              Remove
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
